function slider(key,ends){const [label,min,max,step]=META[key],val=state[key];return `<div class="param"><div class="param-line"><label for="range-${key}">${label}</label><input class="number" aria-label="${label}: valore" data-number="${key}" type="number" min="${min}" max="${max}" step="${step}" value="${format(key,val)}"></div><input id="range-${key}" data-param="${key}" type="range" min="${min}" max="${max}" step="${step}" value="${val}" style="--fill:${(val-min)/(max-min)*100}%">${ends?`<div class="range-ends"><span>${ends[0]}</span><span>${ends[1]}</span></div>`:''}</div>`}
