function syncMasterStates(){state.animateRotation=['rotateX','rotateY','rotateZ'].some(k=>state.motions[k].enabled);state.animateShape=['volume','deform','twist','waves','hole','cut'].some(k=>state.motions[k].enabled);state.animateColor=state.motions.gradientOffset.enabled;state.animateLight=state.lights.some(l=>l.orbit.enabled)}
