function syncNested(path){const meta=pathMeta(path),value=pathValue(state,path);const input=$(`[data-path="${path}"]`),number=$(`[data-number-path="${path}"]`);if(input){input.value=value;input.style.setProperty('--fill',`${(value-meta[1])/(meta[2]-meta[1])*100}%`)}if(number&&number!==document.activeElement)number.value=Number(value.toFixed(3))}
