 if(b.dataset.removeLight){remember();state.lights=state.lights.filter(l=>l.id!==Number(b.dataset.removeLight));syncMasterStates();mark();renderControls()}
 if(b.dataset.lightDepth){const l=state.lights.find(l=>l.id===selectedLightId);if(l){remember();l.z=Math.max(1.5,Math.abs(l.z))*(b.dataset.lightDepth==='back'?-1:1);mark();renderControls()}}
