 if(b.id==='test-backlight'){remember();let l=state.lights.find(l=>l.id===selectedLightId);if(!l){l=newLight(1);state.lights.push(l);selectedLightId=l.id}Object.assign(l,{enabled:true,visible:true,type:'circle',x:0,y:.12,z:-2.6,size:.22,power:2.6,softness:.1,color:'#dfeaff',orbit:{...l.orbit,enabled:true,mode:'cycle',cycles:1,phase:0,direction:1,axis:'y'}});phase=0;syncMasterStates();mark();renderControls();setPlaying(true);toast('Luce in orbita · passa davanti e dietro la figura')}
 if(b.id==='perfect-sphere'){remember();for(const k of ['deform','asymmetry','twist','waves','hole','cut','edge','roundness','taper','bendX','bendY','lobeAmount','pinch','rimRound'])state[k]=0;for(const k of ['volume','stretchX','stretchY','stretchZ','holeAspect','cutAspect'])state[k]=1;for(const k of ['volume','deform','twist','waves','hole','cut'])state.motions[k].enabled=false;syncMasterStates();mark();renderControls();toast('Sfera perfetta · materia e colori conservati')}
