['rotate','move','light'].forEach(m=>$(`#${m}-tool`).onclick=()=>setMode(m));$('#fit').onclick=()=>{remember();state.scale=1;state.positionX=0;state.positionY=0;state.rotateX=0;state.rotateY=0;mark();renderControls()};
function syncHandles(){const container=$('#light-handles'),ids=state.lights.filter(l=>l.enabled).map(l=>l.id);
 if([...container.children].map(el=>Number(el.dataset.lightId)).join(',')!==ids.join(','))container.innerHTML=state.lights.filter(l=>l.enabled).map(l=>`<button class="light-handle" data-light-id="${l.id}" aria-label="Déplacer lumière ${l.id}"></button>`).join('');
 for(const el of container.children){const l=state.lights.find(l=>l.id===Number(el.dataset.lightId)),index=state.lights.indexOf(l),w=Math.max(1,ratio),h=Math.max(1,1/ratio);el.style.left=`${Math.max(4,Math.min(96,(l.x/(3.4*w)+.5)*100))}%`;el.style.top=`${Math.max(4,Math.min(96,(.5-l.y/(3.4*h))*100))}%`;el.style.borderColor=l.color;el.style.color=l.color;el.classList.toggle('behind',l.z<0);el.classList.toggle('selected',l.id===selectedLightId);el.textContent=String(index+1)+(l.z<0?'−':'');el.setAttribute('aria-label',`Trascina luce ${index+1}, ${l.z<0?'dietro':'davanti'} alla figura`);el.title=`Luce ${index+1} · X ${l.x.toFixed(1)}, Y ${l.y.toFixed(1)}, Z ${l.z.toFixed(1)}`;}
}
let drag=null;const pointers=new Map();canvas.addEventListener('pointerdown',e=>{canvas.setPointerCapture(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===1){remember();drag={x:e.clientX,y:e.clientY,s:structuredClone(state)}}else if(pointers.size===2){const a=[...pointers.values()];drag.pinch=Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y);drag.baseScale=state.scale}});
